function trim(s)
    if s == nil then return nil end
    return s:match('^%s*(.-)%s*$')
end

function ltrim(s)
    if s == nil then return nil end
    return s:match('^%s*(.*)')
end

function rtrim(s)
    if s == nil then return nil end
    return s:match('(.-)%s*$')
end

-- Error handling utilities
local Error = {}

function Error.new(code, message, details)
    return {
        code = code,
        message = message,
        details = details or {},
        traceback = debug.traceback(nil, 2),
    }
end

function Error.is_error(val)
    return type(val) == 'table' and val.code ~= nil and val.message ~= nil
end

function Error.try(fn, ...)
    local ok, result = pcall(fn, ...)
    if ok then
        return true, result
    else
        if Error.is_error(result) then
            return false, result
        end
        return false, Error.new('RUNTIME_ERROR', tostring(result))
    end
end

function Error.wrap(fn)
    return function(...)
        return Error.try(fn, ...)
    end
end

return Error

-- Base class pattern
local Class = {}

function Class:new(o)
    o = o or {}
    setmetatable(o, self)
    self.__index = self
    return o
end

-- Example: Animal class
local Animal = Class:new()

function Animal:init(name, sound)
    self.name = name
    self.sound = sound
    return self
end

function Animal:speak()
    return self.name .. ' says ' .. self.sound
end

function Animal:get_name()
    return self.name
end

-- Inheritance: Dog extends Animal
local Dog = Animal:new()

function Dog:init(name)
    Animal.init(self, name, 'Woof')
    self.tricks = {}
    return self
end

function Dog:learn(trick)
    table.insert(self.tricks, trick)
end

function Dog:show_tricks()
    return table.concat(self.tricks, ', ')
end

-- Stack (LIFO)
local Stack = {}
Stack.__index = Stack

function Stack.new()
    return setmetatable({items = {}, count = 0}, Stack)
end

function Stack:push(val)
    self.count = self.count + 1
    self.items[self.count] = val
end

function Stack:pop()
    if self.count == 0 then return nil end
    local val = self.items[self.count]
    self.items[self.count] = nil
    self.count = self.count - 1
    return val
end

function Stack:peek()
    return self.items[self.count]
end

function Stack:is_empty()
    return self.count == 0
end

function Stack:size()
    return self.count
end

-- Queue (FIFO)
local Queue = {}
Queue.__index = Queue

function Queue.new()
    return setmetatable({items = {}, head = 1, tail = 0}, Queue)
end

function Queue:enqueue(val)
    self.tail = self.tail + 1
    self.items[self.tail] = val
end

function Queue:dequeue()
    if self.head > self.tail then return nil end
    local val = self.items[self.head]
    self.items[self.head] = nil
    self.head = self.head + 1
    return val
end

function Queue:peek()
    if self.head > self.tail then return nil end
    return self.items[self.head]
end

function Queue:is_empty()
    return self.head > self.tail
end

function Queue:size()
    return self.tail - self.head + 1
end

function reverse_string(s)
    if s == nil then return nil end
    local chars = {}
    for i = #s, 1, -1 do
        chars[#chars + 1] = s:sub(i, i)
    end
    return table.concat(chars)
end

